-- Original practice instructions. Idempotent append, retaining quizzes and previous material.
with authored(lesson_no,section) as (values
  (0, $curriculum${"heading": "Pierwsza edycja pisma w warsztacie", "text": "Kliknij po zdaniu o rozpoczęciu prac i dopisz „Proponowany termin: wtorek o 9.00”. Zaznacz sam termin, a potem użyj Narzędzia główne → Czcionka → Pogrub albo Ctrl+B. W przeglądarce zobaczysz efekt na zaznaczonym fragmencie. Kliknij w tytuł i wybierz Nagłówek 1 w grupie Style. Sprawdź oddzielnie wygląd słów oraz strukturę tytułu."}$curriculum$::jsonb),
  (1, $curriculum${"heading": "Karty Worda i miejsce szukania narzędzi", "text": "Narzędzia główne (Home) zawierają Czcionkę, Akapit i Style. Wstawianie (Insert) służy do dodawania elementów takich jak tabele, obrazy i numery stron. Układ (Layout) pomaga przygotować stronę i sekcję, a Recenzja (Review) komentarze i śledzenie zmian. Zastanów się, czy zmieniasz istniejący tekst, dodajesz obiekt, ustawiasz stronę czy oddajesz dokument do przeglądu. To podpowiada, którą kartę otworzyć."}$curriculum$::jsonb),
  (3, $curriculum${"heading": "Kursor, zaznaczenie i działanie skrótu", "text": "Kliknięcie ustawia kursor, a przeciągnięcie lub Shift ze strzałkami zaznacza tekst. Ctrl+B w Wordzie na Windows włącza pogrubienie dla zaznaczenia albo dla kolejnego wpisywanego tekstu, gdy masz sam kursor. Ctrl+I działa podobnie dla kursywy, a Ctrl+U dla podkreślenia. Zaznacz tylko nazwę materiału w swoim zdaniu, użyj skrótu, potem dopisz jednostkę i sprawdź, czy przejęła styl."}$curriculum$::jsonb),
  (4, $curriculum${"heading": "Akapit, łamanie wiersza i podział strony", "text": "Enter zaczyna nowy akapit, Shift+Enter przenosi wiersz w ramach tego samego akapitu, a Ctrl+Enter wstawia podział strony. W liście adresowym dwa wiersze mogą należeć do jednego akapitu. Nowy rozdział dokumentu, który ma zacząć się na następnej stronie, używa podziału. W warsztacie kliknij między dwoma akapitami, wybierz Wstawianie → Podział strony i sprawdź miejsce znacznika."}$curriculum$::jsonb),
  (5, $curriculum${"heading": "Styl Nagłówek 1 i lokalne wyróżnienie", "text": "W Wordzie kliknij w akapit tytułu i wybierz Narzędzia główne → Style → Nagłówek 1 albo Ctrl+Alt+1 w wersji Windows. Nagłówek 2 lub Ctrl+Alt+2 daje poziom niżej. W dokumentacji odbiorowej Nagłówek 1 może oznaczać „Wynik odbioru”, a Nagłówek 2 „Usterki do poprawy”. Pogrubienie wykorzystaj do wyróżnienia terminu wewnątrz zdania. Style pomagają zbudować nawigację i spis treści, gdy dokument urośnie."}$curriculum$::jsonb),
  (6, $curriculum${"heading": "Wyrównanie akapitu a ustawienia strony", "text": "Ctrl+L wyrównuje akapit do lewej, Ctrl+E centruje, Ctrl+R wyrównuje do prawej, a Ctrl+J justuje do obu marginesów w desktopowym Wordzie na Windows. Spacja służy do oddzielenia słów, więc użyj narzędzi Akapit do ustawienia tytułu. W warsztacie wyśrodkuj pierwszy akapit, a później przełącz podgląd orientacji w karcie Układ i porównaj zmianę ustawienia całej kartki."}$curriculum$::jsonb),
  (8, $curriculum${"heading": "Cofnij edycję, zachowaj wcześniejszą treść", "text": "Wpisz dwa nowe zdania w różnych akapitach. Zaznacz jedno słowo i pogrub je. Użyj Cofnij lub Ctrl+Z, sprawdź, czy wrócił wcześniejszy wygląd, potem użyj Ponów lub Ctrl+Y. Kolejność zmian ma znaczenie. Przy pracy nad ważnym plikiem najpierw zachowaj oddzielną kopię, jeśli chcesz móc odtworzyć cały stan z poprzedniego dnia."}$curriculum$::jsonb),
  (12, $curriculum${"heading": "Wytnij, kopiuj i dopasuj wklejanie", "text": "Ctrl+C kopiuje zaznaczenie, Ctrl+X je wycina, a Ctrl+V wkleja w miejscu kursora. Przy wklejaniu z innego dokumentu w Wordzie wybierz opcję wklejania zależnie od tego, czy potrzebujesz oryginalnego formatowania, stylów dokumentu docelowego, czy samego tekstu. W warsztacie wklej dane do tabeli i zaznacz kluczową informację ręcznie. To ćwiczenie w korzystaniu z własnego formatowania dokumentu."}$curriculum$::jsonb),
  (13, $curriculum${"heading": "Skrót sprawdź w trzech kontekstach", "text": "Zaznacz słowo i użyj Ctrl+B, by zmienić jego wygląd. Następnie usuń zaznaczenie, włącz Ctrl+B przy kursorze i wpisz nowe słowo. Na końcu kliknij w wiersz tytułu i użyj Ctrl+Alt+1. W drugim przypadku pamiętaj o wyłączeniu pogrubienia przed dalszym pisaniem. W trzecim przypadku styl obejmuje akapit tytułu i może wejść do spisu treści."}$curriculum$::jsonb),
  (16, $curriculum${"heading": "Tabela, którą można uzupełnić", "text": "Wybierz Wstawianie → Tabela. Ustal, jakie dane trafią do kolumn, zanim dodasz kolejne wiersze. W warsztacie wstaw tabelę 2 × 2 z polami Element i Termin. Wpisz poniżej „Protokół odbioru” i „12 listopada”, a potem zmień termin w jednej komórce. W desktopowym Wordzie narzędzia układu tabeli pojawiają się, gdy kursor jest w środku tabeli. Używaj ich do wstawiania wierszy i dopasowania szerokości."}$curriculum$::jsonb),
  (18, $curriculum${"heading": "Komentarz i śledzenie zmian", "text": "W Recenzja → Komentarze wybierz Nowy komentarz, gdy chcesz zapytać o konkretny fragment. Wskaż tekst „data rozpoczęcia” i dopisz „Potwierdzić datę z wykonawcą”. Komentarz zostaje obok treści dokumentu. W desktopowym Wordzie Recenzja → Śledź zmiany rejestruje poprawki do treści, które później można zaakceptować albo odrzucić. Ukrycie znaczników w widoku pozostawia zapisane poprawki w pliku."}$curriculum$::jsonb),
  (20, $curriculum${"heading": "Orientacja jednej strony w dłuższym raporcie", "text": "Karta Układ → Orientacja pozwala zmienić pionową lub poziomą stronę. Gdy tylko jedna część raportu ma być pozioma, w Wordzie zastosuj ustawienia do właściwej sekcji. Układ → Podziały umożliwia ustawienie granic sekcji przed i po tabeli. Podział strony przenosi treść na kolejną stronę, a podział sekcji pozwala wprowadzić inne ustawienia. Po zmianie sprawdź nagłówki, numery stron i dalszą część raportu."}$curriculum$::jsonb),
  (29, $curriculum${"heading": "Samodzielna kontrola pisma", "text": "Ułóż tytuł, dwa krótkie akapity, nagłówek „Terminy” i tabelę z dwiema pozycjami. Wyróżnij tylko datę, którą odbiorca ma potwierdzić. Następnie przejrzyj strukturę dokumentu, długość akapitów, nazwę pliku i stan komentarzy. Przed wysłaniem gotowego PDF sprawdź, czy tabele i podziały nie odcięły ważnej treści. Otwórz eksport i odczytaj ostatnią stronę jak osoba, która dostaje dokument pierwszy raz."}$curriculum$::jsonb)
)
update public.ta_lessons lesson
set material=jsonb_set(lesson.material,'{sections}',
    coalesce(lesson.material->'sections','[]'::jsonb)||jsonb_build_array(authored.section),true),
    updated_at=now()
from authored
where lesson.course_slug='word-skroty' and lesson.lesson_no=authored.lesson_no
and not exists (
  select 1 from jsonb_array_elements(coalesce(lesson.material->'sections','[]'::jsonb)) as existing(section)
  where existing.section->>'heading'=authored.section->>'heading'
)
returning lesson.lesson_no,authored.section->>'heading' as added_section;
